def retry_delay(attempt: int) -> float:
    """Seconds before retry number attempt (zero-based)."""
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if attempt >= 6:
        return 30.0
    return 0.5 * 2**attempt

